package geta_test

import (
	"context"
	"reflect"
	"strings"
	"testing"
	"unicode/utf8"

	"github.com/koji-1009/geta"
)

// ceilingDefaultIn's default holds 4097 code points: one past the pattern
// ceiling.
type ceilingDefaultIn struct {
	D string `query:"d" schema:"pattern=^[0-9a-f]+$,"`
}

// A default beside a pattern longer than the pattern ceiling (4096 code
// points) is refused whatever the Limits.
func TestADefaultBeyondThePatternCeilingIsRefused(t *testing.T) {
	tag := reflect.TypeFor[ceilingDefaultIn]().Field(0).Tag.Get("schema")
	def := tag[strings.Index(tag, "default=")+len("default="):]
	if n := utf8.RuneCountInString(def); n != 4097 {
		t.Fatalf("the default holds %d code points, want 4097", n)
	}
	wide := geta.DefaultLimits
	wide.MaxStringLength = 100000
	long := func(context.Context, *ceilingDefaultIn) (*ok, error) {
		return &ok{true}, nil
	}
	_, err := geta.New(one("/x", get(long)), geta.WithLimits(wide))
	if err == nil || !strings.Contains(err.Error(), "pattern ceiling of 4096") {
		t.Errorf("a default past the ceiling beside a pattern: %v", err)
	}
}
